import java.util.*;

public class MaxFlowSolver {
    static class MaxFlow {
        int[] l;
        int tot;
        int[] cur;
        int[] d;
        int u, v, s, t, src, sink;
        static final int MAX_EDGES = 111111;
        static final int INF = 1000000000;
        class Edge {
            int v, x, cap;
            Edge(int v, int x, int cap) {
                this.v = v;
                this.x = x;
                this.cap = cap;
            }
        }
        Edge[] E;

        MaxFlow() {
            l = new int[210]; // Adjust size as needed
            E = new Edge[MAX_EDGES];
        }

        void add(int u, int v, int cap) {
            E[tot] = new Edge(v, l[u], cap);
            l[u] = tot++;
            E[tot] = new Edge(u, l[v], 0);
            l[v] = tot++;
        }

        void init() {
            Arrays.fill(l, -1);
            tot = 0;
        }

        boolean bfs() {
            Arrays.fill(d, -1);
            System.arraycopy(l, 0, cur, 0, l.length);
            d[src] = 0;
            Queue<Integer> Q = new LinkedList<>();
            Q.offer(src);
            while (!Q.isEmpty()) {
                u = Q.poll();
                for (int i = l[u]; i != -1; i = E[i].x) {
                    v = E[i].v;
                    if (d[v] == -1 && E[i].cap > 0) {
                        d[v] = d[u] + 1;
                        Q.offer(v);
                    }
                }
            }
            return d[sink] != -1;
        }

        int dfs(int u, int in) {
            if (u == sink) return in;
            int flow = 0, f;
            for (int i = cur[u]; i != -1; i = E[i].x) {
                v = E[i].v;
                if (d[v] == d[u] + 1 && E[i].cap > 0) {
                    f = dfs(v, Math.min(in - flow, E[i].cap));
                    if (f > 0) {
                        E[i].cap -= f;
                        E[i ^ 1].cap += f;
                        flow += f;
                        if (flow == in) break;
                    }
                }
            }
            if (flow < in) {
                d[u] = -1;
            }
            return flow;
        }

        int dinic(int _src, int _sink) {
            src = _src;
            sink = _sink;
            int flow = 0;
            while (bfs()) {
                flow += dfs(src, INF);
            }
            return flow;
        }
    }

    static final int N = 15;
    static char[][] field = new char[N][N];
    static char[][] capsule = new char[N][N];
    static int[][] Z = new int[N][N];
    static int[][] S = new int[N][N];
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static int n, t;
    static MaxFlow F = new MaxFlow();

    static boolean inBounds(int i, int j) {
        return i >= 0 && i < n && j >= 0 && j < n;
    }

    static boolean isdigitChar(char ch) {
        return ch >= '1' && ch <= '9';
    }

    static void bfs(int x, int y, int[][] dArr, boolean f) {
        int sx = x, sy = y;
        for (int[] row : dArr) {
            Arrays.fill(row, MaxFlow.INF);
        }
        dArr[x][y] = 0;
        Queue<int[]> Q = new LinkedList<>();
        Q.offer(new int[]{x, y});
        if (f && isdigitChar(capsule[x][y])) {
            F.add(sx * n + sy, sx * n + sy + n * n, MaxFlow.INF);
        }
        while (!Q.isEmpty()) {
            int[] cell = Q.poll();
            int xx = cell[0], yy = cell[1];
            if (dArr[xx][yy] == t) break;
            for (int o = 0; o < 4; o++) {
                int xx2 = xx + dx[o];
                int yy2 = yy + dy[o];
                if (inBounds(xx2, yy2) && dArr[xx2][yy2] == MaxFlow.INF && capsule[xx2][yy2] != 'Y') {
                    if (Z[xx2][yy2] > dArr[xx][yy] + 1 || (Z[xx2][yy2] == dArr[xx][yy] + 1 && isdigitChar(capsule[xx2][yy2]))) {
                        dArr[xx2][yy2] = dArr[xx][yy] + 1;
                        if (f && isdigitChar(capsule[xx2][yy2])) {
                            F.add(sx * n + sy, xx2 * n + yy2 + n * n, MaxFlow.INF);
                        }
                        if (Z[xx2][yy2] > dArr[xx][yy] + 1 || !f) {
                            Q.offer(new int[]{xx2, yy2});
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        int src = n * n * 2;
        int sink = src + 1;
        F.init();
        int problemX = -1, problemY = -1;
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            for (int j = 0; j < n; j++) {
                field[i][j] = row.charAt(j);
                if (field[i][j] == 'Z') {
                    problemX = i;
                    problemY = j;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            for (int j = 0; j < n; j++) {
                capsule[i][j] = row.charAt(j);
                if (isdigitChar(capsule[i][j])) {
                    int capVal = capsule[i][j] - '0';
                    F.add(i * n + j + n * n, sink, capVal);
                }
            }
        }
        bfs(problemX, problemY, Z, false);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (isdigitChar(field[i][j])) {
                    F.add(src, i * n + j, field[i][j] - '0');
                    bfs(i, j, S, true);
                }
            }
        }
        System.out.println(F.dinic(src, sink));
    }
}
